    if ts:
        if not first: first=ts
        last=ts
    t=e.get('type')
    m=e.get('message') or {}
    role=m.get('role') or t
    c=m.get('content')
    parts=[]
    if isinstance(c,str): parts.append(('text',c))
    elif isinstance(c,list):
        for b in c:
            if not isinstance(b,dict): continue
            k=b.get('type')
            if k=='text': parts.append(('text',b.get('text','')))
            elif k=='thinking': parts.append(('think',b.get('thinking','')))
            elif k=='tool_use':
                inp=json.dumps(b.get('input',{}))[:300]
