                r=b.get('content')
                if isinstance(r,list): r=' '.join(x.get('text','') for x in r if isinstance(x,dict))
                parts.append(('res',str(r)[:200]))
    for kind,txt in parts:
        if not txt: continue
        txt=' '.join(str(txt).split())
        if kind=='text' and role=='user': out.append(f"[{ts}] USER: {txt[:lim]}")
        elif kind=='text': out.append(f"[{ts}] ASSISTANT: {txt[:lim]}")
        elif kind=='think': out.append(f"[{ts}] (think) {txt[:600]}")
        elif kind=='tool': out.append(f"[{ts}] TOOL {txt}")
        elif kind=='res': out.append(f"[{ts}]   -> {txt}")
print(f"### span {first} .. {last}")
print('\n'.join(out))
PY
